const concepts=[['Rain trails','Vertical tear trails','빗줄기처럼 이어지는 블루 그래픽.','Depression','#527493'],['Wave state','Rising and falling ribbons','라일락과 앰버가 만드는 오르내리는 리듬.','Bipolar','#785197'],['Branch out','Branching routes','라임과 올리브 위로 갈라지는 자유로운 경로.','ADHD','#99a83f'],['Let it flow','Pressure and release','옥스블러드와 오렌지로 표현한 압력과 해방.','Anger regulation','#a12f38'],['On repeat','Returning loops','웜 아이보리 위로 돌아오는 타우프 루프.','OCD','#b3a58d'],['New perspective','Shifted perspective','페트롤 그린과 겹쳐진 기하학적 시선.','Delusional disorder','#245c53'],['Off the orbit','Offset fragments','라벤더와 민트의 분절된 원형 그래픽.','Schizophrenia','#a28ab4']];
const types=['Accent','Placement','Bold','All-over'];const products=concepts.flatMap((c,i)=>types.map((t,j)=>({id:i*4+j,c:i,t:j,name:c[0],price:32000+j*2000})));let filter='all',expanded=false,sort='featured',selected=null,chosenSize='M';let cart=[];try{cart=JSON.parse(localStorage.getItem('spanky-cart')||'[]').filter(r=>products.some(p=>p.id===r.id)&&['S','M','L','XL'].includes(r.size)&&Number.isInteger(r.qty)&&r.qty>0)}catch{}const $=s=>document.querySelector(s);const money=v=>'₩'+v.toLocaleString('ko-KR');const asset=p=>`assets/product-${p.c}-${p.t}.webp`;const pd=$('#productDialog'),cd=$('#cartDialog'),info=$('#infoDialog');
function save(){localStorage.setItem('spanky-cart',JSON.stringify(cart));$('#count').textContent=cart.reduce((a,r)=>a+r.qty,0)}
function render(){let list=products.filter(p=>filter==='all'||p.t===Number(filter));if(sort==='low')list.sort((a,b)=>a.price-b.price);if(sort==='high')list.sort((a,b)=>b.price-a.price);if(!expanded&&filter==='all'&&sort==='featured')list=[products[7],products[11],products[3],products[19],products[15],products[23],products[27],products[6]];$('#products').innerHTML=list.map(p=>`<article class="product"><div class="product-visual"><span class="tag">COLLECTION 01 / TYPE ${'ABCD'[p.t]}</span><button class="image-button" data-product="${p.id}" aria-label="${p.name} 상세 보기" style="border:0;background:none;width:100%;padding:0"><img src="${asset(p)}" alt="${p.name} ${types[p.t]} 박서 브리프" loading="lazy"></button><button class="quick" data-product="${p.id}" aria-label="${p.name} 옵션 선택">+</button></div><div class="product-title"><h3><button data-product="${p.id}" style="border:0;background:none;padding:0;text-align:left;font-weight:700">${p.name}</button></h3><span class="price">${money(p.price)}</span></div><p class="product-sub">BOXER BRIEF · TYPE ${'ABCD'[p.t]} / ${types[p.t]}</p><div class="swatches"><span class="swatch" style="--c:${concepts[p.c][4]}"></span><span style="font-size:9px;color:#777">S – XL</span></div></article>`).join('');$('#more').hidden=filter!=='all'||expanded||sort!=='featured';}
function detail(id,reset=true){selected=products.find(p=>p.id===id);if(reset)chosenSize='M';const p=selected,c=concepts[p.c];$('#productDetail').innerHTML=`<div class="detail"><div class="detail-image"><img src="${asset(p)}" alt="${p.name} 제품 목업"></div><div><div class="eyebrow">COLLECTION 01 / ${c[1].toUpperCase()}</div><h2>${p.name}</h2><b>${money(p.price)}</b><p>${c[2]}<br>원본 디자인 스튜디오의 ${c[3]} 콘셉트에서 출발한 시각적 이야기입니다.</p><div class="label">GRAPHIC / TYPE ${'ABCD'[p.t]}</div><div class="choices">${types.map((t,i)=>`<button data-type="${i}" class="${i===p.t?'selected':''}">${'ABCD'[i]}</button>`).join('')}</div><div class="label">SIZE <button data-guide style="float:right;border:0;background:none;text-decoration:underline;font-size:10px">사이즈 가이드 ↗</button></div><div class="choices">${['S','M','L','XL'].map(s=>`<button data-size="${s}" class="${s===chosenSize?'selected':''}">${s}</button>`).join('')}</div><button class="button green full" id="add">장바구니 담기 <span>+</span></button><p>디자인 목업 · 가격 및 사이즈는 시연용입니다.<br>패턴 배치와 실제 생산 사양은 달라질 수 있습니다.</p></div></div>`;if(!pd.open)pd.showModal()}
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('visible');setTimeout(()=>$('#toast').classList.remove('visible'),2500)}
function cartView(){const subtotal=cart.reduce((a,r)=>a+products[r.id].price*r.qty,0);$('#cartContent').innerHTML=`<div class="eyebrow">YOUR FIRST LAYER</div><h2>Your bag <span style="color:var(--violet)">(${cart.reduce((a,r)=>a+r.qty,0)})</span></h2>${cart.length?cart.map((r,i)=>{const p=products[r.id];return `<div class="cart-row"><img src="${asset(p)}" alt="${p.name}"><div><h3>${p.name}</h3><p>TYPE ${'ABCD'[p.t]} · ${r.size} / ${money(p.price)}</p><div class="quantity"><button data-qty="${i}" data-delta="-1" aria-label="수량 감소">−</button><span>${r.qty}</span><button data-qty="${i}" data-delta="1" aria-label="수량 증가">+</button></div></div><div>${money(p.price*r.qty)}<br><button class="remove" data-remove="${i}">삭제</button></div></div>`}).join('')+`<div class="total"><span>상품 합계</span><b>${money(subtotal)}</b></div><p class="sample-note">테스트 주문 · 결제 및 실제 배송은 진행되지 않습니다.</p><button id="checkout" class="button green full">주문서 작성 <span>↗</span></button>`:`<p style="padding:45px 0">아직 담긴 상품이 없어요. 나만의 패턴을 찾아보세요.</p><button class="button full" id="continue">쇼핑 계속하기 ↗</button>`}`;if(!cd.open)cd.showModal()}
function guide(){ $('#infoContent').innerHTML='<div class="eyebrow">FIND YOUR FIT</div><h2>Size guide</h2><table><tr><th>사이즈</th><th>허리둘레 (cm)</th></tr><tr><td>S</td><td>68–76</td></tr><tr><td>M</td><td>76–84</td></tr><tr><td>L</td><td>84–92</td></tr><tr><td>XL</td><td>92–100</td></tr></table><p class="notice">기획 단계의 예시 사이즈입니다. 실제 판매 시 최종 제품 실측표로 교체해야 합니다.</p>';info.showModal()}
function checkout(){ $('#cartContent').innerHTML=`<div class="eyebrow">ONE STEP CLOSER</div><h2>Checkout</h2><p class="notice">테스트 주문입니다. 실제 개인정보 대신 예시 정보를 입력하세요. 결제·주문 전송·배송은 진행되지 않습니다. 입력한 배송 정보는 저장되지 않습니다.</p><form id="orderForm"><div class="checkout-grid"><label>받는 분<input name="name" required maxlength="40" placeholder="테스트 고객" autocomplete="off"></label><label>이메일<input name="email" type="email" required placeholder="test@example.com" autocomplete="off"></label><label>연락처<input name="phone" type="tel" required pattern="[0-9+() -]{7,20}" placeholder="010-0000-0000" autocomplete="off"></label><label>우편번호<input name="zip" required pattern="[0-9]{5}" placeholder="00000" autocomplete="off"></label><label class="wide">배송지 주소<input name="address" required maxlength="200" placeholder="예시 도로명 주소" autocomplete="off"></label><label class="wide">상세 주소<input name="detail" maxlength="100" placeholder="동 / 호수 (선택)" autocomplete="off"></label></div><div class="total"><span>합계 · 배송비 무료 (시연)</span><b>${money(cart.reduce((a,r)=>a+products[r.id].price*r.qty,0))}</b></div><label style="display:block;font-size:12px;margin-top:25px"><input type="checkbox" required> 실제 구매가 아닌 테스트 주문임을 확인했습니다.</label><button class="button green full" type="submit">테스트 주문 완료하기 <span>↗</span></button><button type="button" id="backBag" class="load">장바구니로 돌아가기</button></form>`}
document.addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;if(b.classList.contains('close'))return b.closest('dialog').close();if(b.dataset.product!==undefined)return detail(Number(b.dataset.product));if(b.dataset.filter!==undefined){filter=b.dataset.filter;expanded=false;document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('active',x===b));render()}if(b.dataset.type!==undefined)detail(selected.c*4+Number(b.dataset.type),false);if(b.dataset.size){chosenSize=b.dataset.size;detail(selected.id,false)}if(b.hasAttribute('data-guide')||b.id==='sizeGuide')guide();if(b.id==='add'){const row=cart.find(r=>r.id===selected.id&&r.size===chosenSize);if(row)row.qty++;else cart.push({id:selected.id,size:chosenSize,qty:1});save();pd.close();toast('장바구니에 담았습니다. BAG에서 확인하세요.')}if(b.id==='bag')cartView();if(b.id==='more'){expanded=true;render()}if(b.dataset.qty!==undefined){const i=Number(b.dataset.qty);cart[i].qty+=Number(b.dataset.delta);if(cart[i].qty<=0)cart.splice(i,1);save();cartView()}if(b.dataset.remove!==undefined){cart.splice(Number(b.dataset.remove),1);save();cartView()}if(b.id==='checkout')checkout();if(b.id==='backBag')cartView();if(b.id==='continue'){cd.close();document.querySelector('#shop').scrollIntoView({behavior:'smooth'})}if(b.id==='shipping'){$('#infoContent').innerHTML='<h2>배송 · 교환 안내</h2><p class="notice">현재 SPANKY는 디자인 프로젝트 쇼핑몰입니다. 모든 상품과 주문은 시연용이며 실제 판매나 배송은 진행하지 않습니다.</p><p>실제 판매 전 배송 기간·비용, 위생 상품의 교환 및 반품 조건, 판매자 정보와 고객센터를 확정하여 안내할 예정입니다.</p>';info.showModal()}});
document.addEventListener('submit',e=>{if(e.target.id!=='orderForm')return;e.preventDefault();if(!cart.length)return cartView();const id='SP-DEMO-'+crypto.randomUUID().slice(0,8).toUpperCase();const total=cart.reduce((a,r)=>a+products[r.id].price*r.qty,0);$('#cartContent').innerHTML=`<div class="success"><div class="check">✳</div><div class="eyebrow">YOUR MOOD IS IN THE BAG</div><h2>테스트 주문 완료!</h2><p>${id}</p><p>주문 합계 ${money(total)}</p><p class="notice">주문 흐름 체험이 완료되었습니다.<br>실제 결제, 판매자 주문 접수, 이메일 발송 및 배송은 진행되지 않았습니다.</p><button class="button green" id="continue">계속 둘러보기 ↗</button></div>`;cart=[];save()});$('#sort').addEventListener('change',e=>{sort=e.target.value;render()});document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}}));save();render();
if(new URLSearchParams(location.search).get('bag')==='1')cartView();
